    // color encodes the color of an object (see Checker.objDecl for details).
    gocpp::string rec::String(golang::types::color c)
    {
        //Go switch emulation
        {
            auto condition = c;
            int conditionId = -1;
            if(condition == white) { conditionId = 0; }
            else if(condition == black) { conditionId = 1; }
            switch(conditionId)
            {
                case 0:
                    return "white"_s;
                    break;
                case 1:
                    return "black"_s;
                    break;
                default:
                    return "grey"_s;
                    break;
            }
        }
    }

