    bool rec::sameId(object* obj, Package* pkg, gocpp::string name)
    {
        // spec:
        // "Two identifiers are different if they are spelled differently,
        // or if they appear in different packages and are not exported.
        // Otherwise, they are the same."
        if(name != obj->name)
        {
            return false;
        }
        // obj.Name == name
        if(rec::Exported(gocpp::recv(obj)))
        {
            return true;
        }
        // not exported, so packages must be the same (pkg == nil for
        // fields in Universe scope; this can only happen for types
        // introduced via Eval)
        if(pkg == nullptr || obj->pkg == nullptr)
        {
            return pkg == obj->pkg;
        }
        // pkg != nil && obj.pkg != nil
        return pkg->path == obj->pkg->path;
    }

    // less reports whether object a is ordered before object b.
    //
    // Objects are ordered nil before non-nil, exported before
    // non-exported, then by name, and finally (for non-exported
    // functions) by package path.
    bool rec::less(object* a, object* b)
    {
        if(a == b)
        {
            return false;
        }

        // Nil before non-nil.
        if(a == nullptr)
        {
            return true;
        }
        if(b == nullptr)
        {
            return false;
        }

        // Exported functions before non-exported.
        auto ea = isExported(a->name);
        auto eb = isExported(b->name);
        if(ea != eb)
        {
            return ea;
        }

        // Order by name and then (for non-exported names) by package.
        if(a->name != b->name)
        {
            return a->name < b->name;
        }
        if(! ea)
        {
            return a->pkg->path < b->pkg->path;
        }

        return false;
    }

